// @ts-check
import js from "@eslint/js";
import prettier from "eslint-config-prettier";
import tseslint from "typescript-eslint";

/**
 * Never linted, in any repo: build output and generated files, and one policy. A repo's `scripts/`
 * are Node programs, and this preset has no block that gives them Node's globals, so they are left
 * out rather than failed on every `process`.
 */
const NOT_SOURCE = [
  "**/dist/**",
  "**/.next/**",
  "**/.turbo/**",
  "**/.expo/**",
  "**/node_modules/**",
  "**/coverage/**",
  "**/scripts/**/*.mjs",
  "**/next-env.d.ts", // generated by Next (triple-slash refs by design).
];

/**
 * The base preset: ESLint's and typescript-eslint's recommended rules, the two this codebase holds
 * on top (no `any`; no unused names unless underscored), and Prettier's overrides LAST, after
 * whatever `gates` a repo adds, so no gate can switch a formatting rule back on.
 *
 * @param {object} [options]
 * @param {string[]} [options.ignores] globs this repo's lint skips, on top of build output
 * @param {import("typescript-eslint").ConfigArray} [options.gates] the repo's own blocks: its tier gate, its RN-safety gate
 */
export function base({ ignores = [], gates = [] } = {}) {
  return tseslint.config(
    { ignores: [...NOT_SOURCE, ...ignores] },
    js.configs.recommended,
    ...tseslint.configs.recommended,
    {
      rules: {
        "@typescript-eslint/no-explicit-any": "error",
        "@typescript-eslint/no-unused-vars": [
          "error",
          { argsIgnorePattern: "^_", varsIgnorePattern: "^_", ignoreRestSiblings: true },
        ],
      },
    },
    ...gates,
    prettier,
  );
}
